import itertools
# Independent brute-ish check via meson: split 7 = 4 + 3, convolve with adjacency at the seam.
# Count length-n blocks ending/starting in digit j with given sum, no equal adjacents inside block.
def blocks(n):
    # g[s][j] = number of valid length-n strings, sum s, last digit j (and we also need first digit)
    # We'll track first and last digit to glue.
    # h[(first,last)][s] count
    from collections import defaultdict
    if n==1:
        h={}
        for d in range(10):
            h[(d,d)]=defaultdict(int)
            h[(d,d)][d]=1
        return h
    prev=blocks(n-1)
    h={}
    for (f,l),dist in prev.items():
        for nd in range(10):
            if nd==l: continue
            key=(f,nd)
            if key not in h: 
                from collections import defaultdict as dd
                h[key]=dd(int)
            for s,c in dist.items():
                h[key][s+nd]+=c
    return h
A=blocks(4)
B=blocks(3)
# glue: A length4 (digits1-4) with B length3 (digits5-7); seam between pos4 and pos5 must differ
from collections import defaultdict
# index A by last digit -> sum dist ; B by first digit -> sum dist, but seam constraint last(A)!=first(B)
Alast=defaultdict(lambda: defaultdict(int))
for (f,l),dist in A.items():
    for s,c in dist.items():
        Alast[l][s]+=c
Bfirst=defaultdict(lambda: defaultdict(int))
for (f,l),dist in B.items():
    for s,c in dist.items():
        Bfirst[f][s]+=c
total=0
for la in range(10):
    for fb in range(10):
        if la==fb: continue
        for sa,ca in Alast[la].items():
            need=30-sa
            total+=ca*Bfirst[fb].get(need,0)
print('glued sum30:',total)
